// rk-tube: corner brand overlay, per the owner's approved design reference:
// "RK Tube" top right with "disfrutar sin anuncios" below it.
// Non-interactive (pointer-events: none) so it never interferes with remote navigation.

// rk-tube: exact brand art supplied by the owner (red play + "RK Tube" +
// "disfrutar sin anuncios"), embedded so it renders pixel-identical, without
// redrawing or cropping. Aspect ratio is preserved (height: auto).
const RK_BRAND_ART = 'data:image/jpeg;base64,';

// Replace only the native guide wordmark on known Principal routes.
// Never cover other UI or change sign-in elements.
function mountBrand() {
    if (!document.body || !document.head) return setTimeout(mountBrand, 500);
    const previous = [];
    function restore() {
        while (previous.length) {
            const item = previous.pop();
            if (item.node.style.backgroundImage === item.applied) item.node.style.backgroundImage = item.original;
        }
    }
    function visible(node) {
        return node && node.getAttribute('aria-hidden') !== 'true' && node.getClientRects().length > 0 && getComputedStyle(node).visibility !== 'hidden';
    }
    function syncBrand() {
        const hash = location.hash.substring(1);
        const home = hash === '/' || /(?:[?&]c=)(?:FEtopics|FEwhat_to_watch)(?:&|$)/.test(hash);
        const guide = document.querySelector('ytlr-guide-response');
        const signin = Array.from(document.querySelectorAll('ytlr-welcome, ytlr-url-sign-in-renderer, ytlr-sign-in-renderer')).some(visible);
        if (!home || !guide || signin || !visible(guide)) { restore(); return; }
        const logo = guide.querySelector('ytlr-logo-entity ytlr-thumbnail-details');
        if (!logo || previous.some(item => item.node === logo)) return;
        const original = logo.style.backgroundImage;
        if (!/branding\/livingroom\/youtube\/wordmark/.test(original)) return;
        logo.style.backgroundImage = 'url("' + RK_BRAND_ART + '")';
        previous.push({ node: logo, original, applied: logo.style.backgroundImage });
    }
    window.addEventListener('hashchange', syncBrand);
    setInterval(syncBrand, 700);
    syncBrand();
}
mountBrand();
